INSERT INTO `soal` (`id_soal`, `id_ujian`, `soal`, `pilihan_1`, `pilihan_2`, `pilihan_3`, `pilihan_4`, `pilihan_5`, `kunci`, `status`) VALUES
(404, 30, 'Kecepatan maksimum transfer data kabel coaxial adalah..', '1 MBps', '10 MBps', '100 MBps', '10 KBps', '100 KBps', 2, 'Y'),
(415, 31, '<p>Merupakan antarmuka untuk media penyimpanan generasi terbaru.&nbsp;bisa digunakan untuk menghubungkan Hard Disk dengan sistem komputer.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Adalah fungsi dari..</p>\r\n', 'Flasdisk', 'Hardisk', 'Port Memori', 'Port IDE', 'Port Sata', 5, 'Y'),
(416, 31, '<p>Perangkat dimana sistemoperasi komputer berada adalah..</p>\r\n', 'Keyboard', 'RAM', 'Mainboard', 'Prosesor', 'Hardisk', 5, 'Y'),
(417, 31, '<p>Berikut ini adalah alat penyimpanan exsternal, <strong><em>Kecuali</em></strong>..</p>\r\n', 'RAM', 'Hardisk', 'Disket', 'CD', 'Hardisk exsternal', 1, 'Y'),
(418, 31, '<p>Apa kepanjangan dari RAM...</p>\r\n', 'Randome akses Memori', 'Random Akses Menyeluruh', 'Random Access Memory', 'Random Akses Memori', 'Randome Access Memorry', 3, 'Y'),
(419, 31, '<p>diantara komponen berikut yang berfungsi sebagai penyimpanan data adalah.</p>\r\n', 'CD-ROM', 'Hardisk', 'DVD', 'Monitor', 'Prosesor', 2, 'Y'),
(420, 31, '<p>Berikut ini yang merupakan perangkat Input&nbsp;adalah..</p>\r\n', 'Prosesor', 'Monitor', 'Audio', 'Mouse', 'Printer', 4, 'Y'),
(421, 31, '<p><strong>Berikut ini yang merupakan perangkat Output adalah..</strong></p>\r\n', 'Prosesor', 'Monitor', 'mouse', 'Joystik', 'RAM', 2, 'Y'),
(422, 31, '<p>Apa fungsi dari port usb..</p>\r\n', 'digunakan untuk antarmuka dengan periferal atau peralatan eksternal generasi baru yang menggantikan port paralel dan Serial.', 'untuk memasang periferal kecepatan rendah dengan lebar data delapan bit. Biasanya digunakan untuk memasang printer sebelum generasi USB', 'digunakan untuk memasang periferal kecepatan rendah dengan mode transfer data serial. Namun saat ini jarang digunakan', 'merupakan antarmuka untuk media penyimpanan generasi terbaru. Port SATA bisa digunakan untuk menghubungkan Hard Disk dengan sistem komputer', 'merupakan antarmuka media penyimpanan sebelum generasi SATA', 1, 'Y'),
(423, 31, '<p>Apa fungsi dari port IDE..</p>\r\n', 'digunakan untuk antarmuka dengan periferal atau peralatan eksternal generasi baru yang menggantikan port paralel dan Serial.', 'untuk memasang periferal kecepatan rendah dengan lebar data delapan bit. Biasanya digunakan untuk memasang printer sebelum generasi USB', 'digunakan untuk memasang periferal kecepatan rendah dengan mode transfer data serial. Namun saat ini jarang digunakan', 'merupakan antarmuka untuk media penyimpanan generasi terbaru. Port SATA bisa digunakan untuk menghubungkan Hard Disk dengan sistem komputer', 'merupakan antarmuka media penyimpanan sebelum generasi SATA', 5, 'Y'),
(424, 31, '<p>Apa fungsi dari port Paralel..</p>\r\n', 'digunakan untuk antarmuka dengan periferal atau peralatan eksternal generasi baru yang menggantikan port paralel dan Serial.', 'untuk memasang periferal kecepatan rendah dengan lebar data delapan bit. Biasanya digunakan untuk memasang printer sebelum generasi USB', 'digunakan untuk memasang periferal kecepatan rendah dengan mode transfer data serial. Namun saat ini jarang digunakan', '\r\nmerupakan antarmuka untuk media penyimpanan generasi terbaru. bisa digunakan untuk menghubungkan Hard Disk dengan sistem komputer', 'merupakan antarmuka media penyimpanan sebelum generasi SATA', 2, 'Y'),
(425, 31, '<p><img alt=\"\" src=\"/vendor/kcfinder/upload/files/image-4.png\" style=\"height:295px; width:669px\" /></p>\r\n\r\n<p>nama komponen pada nomer 17..</p>\r\n', 'Periferal', 'USB', 'Port RJ45', 'Audio', 'PS2', 5, 'Y'),
(426, 31, '<p><img alt=\"\" src=\"/vendor/kcfinder/upload/files/image-4.png\" style=\"height:290px; width:658px\" /></p>\r\n\r\n<p>Nama komponen no 22</p>\r\n', 'Periferal', 'USB', 'Port RJ45', 'Audio', 'PS2', 3, 'Y'),
